import { spawn } from "node:child_process";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { readFileSync } from "node:fs";
import type { RunOptions } from "../types.js";

export interface ProcessResult {
  code: number | null;
  stdout: string;
  stderr: string;
  timedOut: boolean;
  aborted: boolean;
}
export function frameworkCli(name: string, binName = name): string {
  const require = createRequire(join(process.cwd(), "package.json"));
  const manifestPath = require.resolve(`${name}/package.json`);
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
  const bin =
    typeof manifest.bin === "string" ? manifest.bin : manifest.bin?.[binName];
  if (typeof bin !== "string")
    throw new Error(`No CLI found for installed ${name}`);
  return join(dirname(manifestPath), bin);
}

/** Invoke installed framework code without a shell or downloads; terminate its process group on cancellation. */
export function executeNode(
  args: string[],
  options: RunOptions,
): Promise<ProcessResult> {
  return new Promise((resolve, reject) => {
    if (options.signal?.aborted) {
      reject(new Error("Test run aborted"));
      return;
    }
    const child = spawn(process.execPath, args, {
      shell: false,
      env: { ...process.env, ...options.env },
      detached: process.platform !== "win32",
    });
    let stdout = "",
      stderr = "",
      timedOut = false,
      aborted = false,
      overflow = false;
    let killTimer: ReturnType<typeof setTimeout> | undefined;
    const kill = (signal: NodeJS.Signals) => {
      try {
        if (process.platform !== "win32" && child.pid)
          process.kill(-child.pid, signal);
        else child.kill(signal);
      } catch {
        /* Process already exited. */
      }
    };
    const stop = () => {
      kill("SIGTERM");
      killTimer ??= setTimeout(() => kill("SIGKILL"), 1000);
    };
    const onAbort = () => {
      aborted = true;
      stop();
    };
    options.signal?.addEventListener("abort", onAbort, { once: true });
    const timer = setTimeout(() => {
      timedOut = true;
      stop();
    }, options.timeout ?? 30000);
    const append = (kind: "stdout" | "stderr", data: string) => {
      if (overflow) return;
      if (stdout.length + stderr.length + data.length > 16 * 1024 * 1024) {
        overflow = true;
        stderr += "\nFramework output exceeded 16 MiB";
        stop();
        return;
      }
      if (kind === "stdout") stdout += data;
      else stderr += data;
    };
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (data) => append("stdout", data));
    child.stderr.on("data", (data) => append("stderr", data));
    const cleanup = () => {
      clearTimeout(timer);
      if (killTimer) clearTimeout(killTimer);
      options.signal?.removeEventListener("abort", onAbort);
    };
    child.once("error", (error) => {
      cleanup();
      reject(error);
    });
    child.once("close", (code) => {
      if (timedOut || aborted || overflow) kill("SIGKILL");
      cleanup();
      resolve({ code: overflow ? 1 : code, stdout, stderr, timedOut, aborted });
    });
  });
}
import type {
  TestCase,
  TestResult,
  RunOptions,
  TestFrameworkAdapter,
} from "../types.js";

export class WorkerPool {
  private active?: Promise<TestResult[]>;
  constructor(private maxWorkers = 4) {
    if (!Number.isInteger(maxWorkers) || maxWorkers < 1)
      throw new Error("parallel must be a positive integer");
  }
  async executeTests(
    tests: TestCase[],
    adapter: TestFrameworkAdapter,
    options: RunOptions,
  ): Promise<TestResult[]> {
    if (this.active) throw new Error("Worker pool is already running");
    const retries = options.retries ?? 0;
    if (!Number.isInteger(retries) || retries < 0)
      throw new Error("retries must be a nonnegative integer");
    if (
      options.timeout !== undefined &&
      (!Number.isFinite(options.timeout) || options.timeout <= 0)
    )
      throw new Error("timeout must be positive");
    let next = 0,
      completed = 0;
    const grouped: TestResult[][] = new Array(tests.length);
    const worker = async () => {
      while (next < tests.length) {
        const index = next++,
          test = tests[index];
        if (options.signal?.aborted) {
          grouped[index] = [
            {
              id: test.id,
              status: "skipped",
              duration: 0,
              metadata: { cancelled: true },
            },
          ];
          await options.onTestComplete?.(grouped[index][0]);
          completed++;
          options.onProgress?.({
            completed,
            total: tests.length,
            current: test,
          });
          continue;
        }
        await options.onTestStart?.(test);
        for (let attempt = 0; attempt <= retries; attempt++) {
          try {
            const results = await adapter.run([test], {
              ...options,
              onProgress: undefined,
              onTestStart: undefined,
              onTestComplete: undefined,
            });
            if (!results.length)
              throw new Error(
                "Adapter returned no results for a discovered test",
              );
            if (
              results.some(
                (result) =>
                  !result ||
                  typeof result.id !== "string" ||
                  !["passed", "failed", "skipped", "timeout"].includes(
                    result.status,
                  ) ||
                  !Number.isFinite(result.duration) ||
                  result.duration < 0,
              )
            )
              throw new Error("Adapter returned an invalid test result");
            grouped[index] = results.map((result) => ({
              ...result,
              metadata: { ...result.metadata, attempts: attempt + 1 },
            }));
          } catch (error) {
            grouped[index] = [
              {
                id: test.id,
                status: "failed",
                duration: 0,
                error: { message: String(error) },
              },
            ];
          }
          if (
            options.signal?.aborted ||
            !grouped[index].some(
              (result) =>
                result.status === "failed" || result.status === "timeout",
            )
          )
            break;
        }
        for (const result of grouped[index])
          await options.onTestComplete?.(result);
        completed++;
        options.onProgress?.({ completed, total: tests.length, current: test });
      }
    };
    this.active = Promise.allSettled(
      Array.from({ length: Math.min(this.maxWorkers, tests.length) }, worker),
    ).then((settled) => {
      const failed = settled.find((result) => result.status === "rejected");
      if (failed?.status === "rejected") throw failed.reason;
      return grouped.flat();
    });
    try {
      return await this.active;
    } finally {
      this.active = undefined;
    }
  }
  async shutdown(): Promise<void> {
    await this.active;
  }
}
