      issueCreate(input: { teamId: $teamId, title: $title, description: $description }) {
        success
        issue {
          id
          identifier
          title
          url
        }
      }
    }
  `;

  const result = await linearRequest<{
    issueCreate: {
      success: boolean;
      issue: {
        id: string;
        identifier: string;
        title: string;
        url: string;
      };
    };
  }>(mutation, config, { teamId, title, description });

  return result.issueCreate.issue;
}
