  if (point[2] !== undefined && !isFiniteNumber(point[2])) {
    return invalidScene(`${path}[2] must be a finite number when provided.`, {
      path,
      value: point,
    });
  }

  return {
    ok: true,
    data:
      point[2] === undefined
        ? [point[0], point[1]]
        : [point[0], point[1], point[2]],
