  if (!y.ok) return y;
  const w = normalizeOptionalNumber(elementData.w, 100, `elements[${index}].w`);
  if (!w.ok) return w;
  const h = normalizeOptionalNumber(elementData.h, 100, `elements[${index}].h`);
