    const scene = context.getScene();
    const point = screenToCanvas(
      { x: e.clientX, y: e.clientY },
      scene.camera,
      canvas
    );

    this.currentPoints.push([
      point.x - this.currentElement.x,
      point.y - this.currentElement.y,
      e.pressure || 0.5,
    ]);

