    context.updateElement(this.currentElementId, {
      points: this.currentPoints,
      w,
      h,
    });
  }

  handlePointerUp(e: PointerEvent, context: ToolContext): void {
    this.currentElement = null;
    this.currentElementId = null;
    this.currentPoints = [];
  }
