      });
    },
    async beginBotProducer(input: Omit<ProducerIntent, 'id' | 'state' | 'createdAt'>): Promise<ProducerIntent> {
      return transaction(async tx => {
        await assertBotWritable(tx, input.botId, input.namespace);
        const existing = await tx.findMany<ProducerIntent>({ model: 'botProducers', where: botWhere(input.botId, input.namespace) });
