    async reconcileBotProducer(id: string, namespace: string, proof: { operationStopped: true }): Promise<void> {
      if (proof.operationStopped !== true) throw blocked();
      await adapter.update({ model: 'botProducers', where: where(id, namespace), data: { state: 'settled' } });
    },
    async completeBotDeletion(id: string, namespace: string): Promise<void> {
