python3 - <<'PY'
import json,subprocess,os,concurrent.futures,collections
x=json.load(open('/tmp/sf-next-gate-check-runs.json')); env=dict(os.environ,GH_CONFIG_DIR=os.path.expanduser('~/.config/gh-other'))
jobs=[(p['pr'],c) for p in x for c in p['data']['check_runs'] if c['conclusion']=='failure' and c['output']['annotations_count']]
def one(pc):
 p,c=pc;r=subprocess.run(['gh','api',c['output']['annotations_url']],env=env,text=True,capture_output=True)
 return {'pr':p,'name':c['name'],'id':c['id'],'annotations':json.loads(r.stdout) if r.returncode==0 else r.stderr}
with concurrent.futures.ThreadPoolExecutor(max_workers=5) as ex:data=list(ex.map(one,jobs))
json.dump(data,open('/tmp/sf-next-gate-annotations.json','w'),indent=2)
g=collections.defaultdict(list)
for p in data:
 for a in p['annotations']:g[a['message']].append((p['pr'],p['name'],a['path'],a['start_line']))
for msg,rows in g.items():print('\nSIGNATURE',msg,'\nAFFECTED',rows)
PY

