async function collectDesignFindings(
  repoRoot: string,
  artifactRoot: string,
  checkpoints: CheckpointIndexEntry[],
): Promise<{
  findings: DesignFinding[];
  warnings: string[];
}> {
  const findings: DesignFinding[] = [];
  const warnings: string[] = [];

  for (const checkpoint of checkpoints) {
    try {
      const bundle = await loadCheckpointAuditBundle({
        repoRoot,
        artifactRoot,
        checkpointId: checkpoint.checkpointId,
      });
      const audit = auditDesignBundle(bundle, {
        warnOnMissingTokenMap: false,
      });
      findings.push(...audit.findings);
      warnings.push(...audit.warnings);
    } catch {
      continue;
    }
  }

  return {
    findings: dedupeBySignature(findings, (finding) => `${finding.category}:${finding.summary}`),
    warnings: dedupeBySignature(warnings, (warning) => warning),
  };
}

async function readRegressionIndex(
  repoRoot: string,
  artifactRoot: string,
): Promise<RegressionIndexEntry[]> {
  const diffRoot = path.resolve(repoRoot, artifactRoot, 'diffs');
  const directories = await safeReaddir(diffRoot);
  const regressions: RegressionIndexEntry[] = [];

  for (const directory of directories) {
    if (!directory.isDirectory()) {
      continue;
    }

    const summaryPath = path.resolve(diffRoot, directory.name, 'diff.json');
    try {
      const summary = await readJson<DiffManifest>(summaryPath);
      regressions.push({
        baselineKey: summary.baselineKey,
        summaryPath: toRepoRelative(repoRoot, summaryPath),
        diffPath: path.posix.join(toRepoRelative(repoRoot, path.resolve(diffRoot, directory.name)), 'diff.png'),
        pixelDiffPercent: summary.pixelDiffPercent,
        changedPixels: summary.changedPixels,
        totalPixels: summary.totalPixels,
      });
    } catch {
      continue;
    }
  }

  return regressions.sort((left, right) => left.baselineKey.localeCompare(right.baselineKey));
}

async function* iterateIndexedEvents(
  repoRoot: string,
  relativePath: string | undefined,
  category: CorrelationEventRecord['category'],
  prefix: string,
): AsyncGenerator<IndexedRuntimeEvent> {
  if (!relativePath) {
    return;
  }

  try {
    let index = 0;
    for await (const record of iterateEventSinkFamily(repoRoot, relativePath)) {
      const payload = record.payload;
      const ts = typeof payload.ts === 'string' ? payload.ts : undefined;
      yield {
        eventId: `${prefix}_${++index}`,
        category,
        sinkPath: record.relativePath,
        lineNumber: record.lineNumber,
        payload,
        ...(ts ? { ts } : {}),
      };
    }
  } catch (error) {
    if (isMissing(error)) {
      return;
    }

    throw error;
  }
export interface CorrelationEventRecord {
  eventId: string;
  category: 'action' | 'console' | 'page-error' | 'network' | 'devserver-stdout' | 'devserver-stderr';
  sinkPath: string;
  lineNumber: number;
  payload: Record<string, unknown>;
}

export interface CorrelationCheckpointRecord {
  checkpointId: string;
  name: string;
  manifestPath: string;
  artifactPaths: string[];
  createdAt: string;
  url: string;
}

export interface RootCauseHypothesis {
  hypothesisId: string;
  confidence: number;
  statement: string;
  evidenceEventIds: string[];
  evidenceArtifactPaths: string[];
}

export interface RootCauseCorrelationResult {
  hypotheses: RootCauseHypothesis[];
  unresolvedReason?: string;
}

export interface CorrelateRootCauseInput {
  actions: CorrelationEventRecord[];
  consoleEvents: CorrelationEventRecord[];
  pageErrors: CorrelationEventRecord[];
  networkEvents: CorrelationEventRecord[];
  checkpoints: CorrelationCheckpointRecord[];
}

const UNDEFINED_PROPERTY_PATTERN =
  /Cannot read properties of undefined \(reading ['"](?<property>[^'"]+)['"]\)/i;

/** Retain only the first witnesses used by the deterministic correlation rules. */
export function createCorrelationAccumulator() {
  const records = new Map<string, CorrelationEventRecord>();
  return {
    add(event: CorrelationEventRecord) {
      for (const [key, matches] of Object.entries(correlationPredicates)) {
        if (!records.has(key) && matches(event)) records.set(key, event);
      }
    },
    events(): CorrelationEventRecord[] { return [...new Set(records.values())]; },
  };
}

const correlationPredicates: Record<string, (event: CorrelationEventRecord) => boolean> = {
  consolePlan: event => event.category === 'console' && /reading ['"]plan['"]/i.test(getConsoleMessage(event)),
  pagePlan: event => event.category === 'page-error' && /reading ['"]plan['"]/i.test(getPageErrorMessage(event)),
