/**
 * Export service: auditorPack() builds AuditorPack with optional frameworkId/since filters
 * and enforces exportMaxBytes (EXPORT-001, LIMIT-001).
 */

import type { CompfnEnvelope } from "../errors.js";
import type { Control } from "../control.js";
import type { Framework } from "../framework.js";
import type { Evidence } from "../evidence.js";
import type { AuditorPack } from "../export-types.js";
import type { Logger } from "../logger.js";
import { EXPORT_MAX_BYTES_DEFAULT } from "../constants.js";
import { defaultLogger } from "../logger.js";

export interface ExportServiceConfig {
  /** Load single framework by id */
  getFramework: (id: string) => Promise<CompfnEnvelope<Framework>>;
  /** Load all frameworks */
  listFrameworks: () => Promise<CompfnEnvelope<Framework[]>>;
  /** Load single control by id */
  getControl: (id: string) => Promise<CompfnEnvelope<Control>>;
  /** Load all controls (no filter) or with optional filters */
  listControls: (filters?: { category?: string; tags?: string[] }) => Promise<CompfnEnvelope<Control[]>>;
  /** List evidence with optional controlId, frameworkId, type, since */
  listEvidence: (filters: {
    controlId?: string;
    frameworkId?: string;
    type?: string;
    since?: number;
  }) => Promise<CompfnEnvelope<Evidence[]>>;
  exportMaxBytes?: number;
  logger?: Logger;
}

/**
 * Build set of control IDs from framework(s) requirements.
 */
function controlIdsFromFrameworks(frameworks: Framework[]): Set<string> {
  const set = new Set<string>();
  for (const fw of frameworks) {
    for (const req of fw.requirements) {
      for (const cid of req.controlIds) {
        set.add(cid);
      }
    }
  }
  return set;
}

export function createExportService(config: ExportServiceConfig) {
  const exportMaxBytes = config.exportMaxBytes ?? EXPORT_MAX_BYTES_DEFAULT;
  const logger = config.logger ?? defaultLogger;

  return {
    async auditorPack(options: {
      frameworkId?: string;
      since?: number;
    }): Promise<CompfnEnvelope<AuditorPack>> {
      logger.info("export.requested", {
        event: "export.requested",
        frameworkId: options.frameworkId,
      });

      // 1) Load frameworks: one by id or all
      let frameworks: Framework[];
      if (options.frameworkId != null && options.frameworkId !== "") {
        const r = await config.getFramework(options.frameworkId);
        if (!r.ok) return r;
        frameworks = [r.result];
      } else {
        const r = await config.listFrameworks();
        if (!r.ok) return r;
        frameworks = r.result;
      }

      const controlIdSet = controlIdsFromFrameworks(frameworks);

      // 2) Load controls: scoped to framework controlIds or all
      let controls: Control[];
      if (options.frameworkId != null && options.frameworkId !== "") {
        controls = [];
        for (const cid of controlIdSet) {
          const r = await config.getControl(cid);
          if (r.ok) controls.push(r.result);
          else if (r.error.code !== "CONTROL_NOT_FOUND") return r;
        }
      } else {
        const r = await config.listControls();
        if (!r.ok) return r;
        controls = r.result;
      }

      // 3) Load evidence: optional frameworkId and since
      const evidenceFilters: { frameworkId?: string; since?: number } = {};
      if (options.frameworkId != null && options.frameworkId !== "") {
        evidenceFilters.frameworkId = options.frameworkId;
      }
      if (options.since != null && Number.isFinite(options.since)) {
        evidenceFilters.since = options.since;
      }
      const evRes = await config.listEvidence(evidenceFilters);
      if (!evRes.ok) return evRes;
      const evidence = evRes.result;

      // 4) Build mapping from framework.requirements
      const mapping: Array<{ requirementId: string; controlIds: string[] }> = frameworks.flatMap((fw) =>
        fw.requirements.map((req) => ({
          requirementId: req.requirementId,
          controlIds: [...req.controlIds],
        }))
      );

      const result: AuditorPack = {
        exportedAt: Date.now(),
        frameworkId: options.frameworkId,
        controls,
        frameworks,
        evidence,
        mapping,
      };

      // 5) Size check
      const serialized = JSON.stringify(result);
      const size = new TextEncoder().encode(serialized).length;
      if (size > exportMaxBytes) {
        return {
          ok: false,
          error: {
            code: "EXPORT_FAILED",
            message: `Export size ${size} exceeds limit ${exportMaxBytes}`,
            details: { size, limit: exportMaxBytes },
          },
        };
      }

      logger.info("export.completed", {
        event: "export.completed",
        frameworkId: options.frameworkId,
        sizeBytes: size,
      });

      return { ok: true, result };
    },
  };
}
/**
 * Readiness service: forControl, forFramework.
 *
 * Policy (deterministic; same evidence set + config → same status):
 * - not_applicable: when the latest scoping_decision evidence (by evidence.timestamp) for the control
 *   has payload.status === "not_applicable". Latest = highest timestamp; tie-break by createdAt then id.
 * - compliant: when applicable and there is at least one evidence record with outcome "pass"
 *   (excluding type scoping_decision) and evidence.timestamp within the policy window
 *   (readinessWindowDays days from now; config.readinessWindowDays ?? 90).
 * - not_compliant: when applicable and no such pass evidence exists within the window.
 *
 * All timestamps in ms (Unix). Window: now - (readinessWindowDays * 24 * 60 * 60 * 1000).
 */

import type { CompfnEnvelope } from "../errors.js";
import type { ControlReadiness, FrameworkReadiness, ReadinessStatus } from "../readiness.js";
import type { Evidence } from "../evidence.js";
import type { Framework } from "../framework.js";
import { READINESS_WINDOW_DAYS_DEFAULT } from "../constants.js";

export interface ReadinessServiceConfig {
  /** Get control by id; returns envelope (CONTROL_NOT_FOUND when missing). */
  getControl: (id: string) => Promise<CompfnEnvelope<{ id: string }>>;
  /** Get framework by id; returns envelope (FRAMEWORK_NOT_FOUND when missing). */
  getFramework: (id: string) => Promise<CompfnEnvelope<Framework>>;
  /** List evidence for a control (no since filter; we apply window in logic). */
  listEvidence: (controlId: string) => Promise<CompfnEnvelope<Evidence[]>>;
  /** Policy window in days. Evidence with timestamp within this many days from now counts for compliant. */
  readinessWindowDays?: number;
}

function now(): number {
  return Date.now();
}

/**
 * Latest scoping_decision for control: the one with greatest timestamp; tie-break by createdAt, then id.
 * Returns undefined if no scoping_decision evidence.
 */
function latestScopingDecision(evidence: Evidence[]): Evidence | undefined {
  const scoping = evidence.filter((e) => e.type === "scoping_decision");
  if (scoping.length === 0) return undefined;
  scoping.sort((a, b) => {
    if (b.timestamp !== a.timestamp) return b.timestamp - a.timestamp;
    if (b.createdAt !== a.createdAt) return b.createdAt - a.createdAt;
    return b.id.localeCompare(a.id);
  });
  return scoping[0];
}

/**
 * Evidence that counts for pass-within-window: type !== scoping_decision, outcome === "pass", timestamp >= windowStart.
 */
function hasPassInWindow(
  evidence: Evidence[],
  windowStartMs: number
): { compliant: boolean; lastEvidenceAt?: number; lastEvidenceId?: string } {
  let maxTs = -1;
  let lastEvidenceId: string | undefined;
  let foundPassInWindow = false;
  for (const e of evidence) {
    if (e.timestamp > maxTs) {
      maxTs = e.timestamp;
      lastEvidenceId = e.id;
    }
    if (e.type === "scoping_decision") continue;
    if (e.outcome === "pass" && e.timestamp >= windowStartMs) {
      foundPassInWindow = true;
    }
  }
  return {
    compliant: foundPassInWindow,
    lastEvidenceAt: maxTs >= 0 ? maxTs : undefined,
    lastEvidenceId,
  };
}

/**
 * Requirement IDs (from the given framework) that map to this controlId.
 */
function requirementIdsForControl(framework: Framework, controlId: string): string[] {
  const ids: string[] = [];
  for (const req of framework.requirements) {
    if (req.controlIds.includes(controlId)) {
      ids.push(req.requirementId);
    }
  }
  return ids;
}

export function createReadinessService(config: ReadinessServiceConfig) {
  const windowDays = config.readinessWindowDays ?? READINESS_WINDOW_DAYS_DEFAULT;
  const windowMs = windowDays * 24 * 60 * 60 * 1000;

  async function computeControlReadiness(
    controlId: string,
    frameworkId?: string
  ): Promise<CompfnEnvelope<ControlReadiness>> {
    const controlRes = await config.getControl(controlId);
    if (!controlRes.ok) {
      return controlRes;
    }

    const evidenceRes = await config.listEvidence(controlId);
    if (!evidenceRes.ok) {
      return evidenceRes;
    }
    const evidence = evidenceRes.result;

    const latestScoping = latestScopingDecision(evidence);
    if (
      latestScoping &&
      (latestScoping.payload?.status as string) === "not_applicable"
    ) {
      const byTs = [...evidence].sort((a, b) => b.timestamp - a.timestamp);
      const last = byTs[0];
      const result: ControlReadiness = {
        controlId,
        status: "not_applicable",
        lastEvidenceAt: last ? last.timestamp : undefined,
        lastEvidenceId: last ? last.id : undefined,
      };
      if (frameworkId) {
        const fwRes = await config.getFramework(frameworkId);
        if (!fwRes.ok) return fwRes;
        if (fwRes.ok) {
          result.requirementIds = requirementIdsForControl(fwRes.result, controlId);
        }
      }
      return { ok: true, result };
    }

    const windowStart = now() - windowMs;
    const { compliant, lastEvidenceAt, lastEvidenceId } = hasPassInWindow(
      evidence,
      windowStart
    );
    const status: ReadinessStatus = compliant ? "compliant" : "not_compliant";
    const result: ControlReadiness = {
      controlId,
      status,
      lastEvidenceAt,
      lastEvidenceId,
    };
    if (frameworkId) {
      const fwRes = await config.getFramework(frameworkId);
      if (!fwRes.ok) return fwRes;
        if (fwRes.ok) {
        result.requirementIds = requirementIdsForControl(fwRes.result, controlId);
      }
    }
    return { ok: true, result };
  }

  return {
    async forControl(
      controlId: string,
      frameworkId?: string
    ): Promise<CompfnEnvelope<ControlReadiness>> {
      return computeControlReadiness(controlId, frameworkId);
    },

    async forFramework(
      frameworkId: string
    ): Promise<CompfnEnvelope<FrameworkReadiness>> {
      const fwRes = await config.getFramework(frameworkId);
      if (!fwRes.ok) {
        return fwRes;
      }
      const framework = fwRes.result;

      const controlIds = new Set<string>();
      for (const req of framework.requirements) {
        for (const cid of req.controlIds) {
          controlIds.add(cid);
        }
      }

      const controlReadiness: ControlReadiness[] = [];
      let frameworkStatus: ReadinessStatus = "compliant";
      for (const cid of controlIds) {
        const cr = await computeControlReadiness(cid, frameworkId);
        if (!cr.ok) {
          return cr;
        }
        controlReadiness.push(cr.result);
        if (cr.result.status === "not_compliant") {
          frameworkStatus = "not_compliant";
        }
      }

      return {
        ok: true,
        result: {
          frameworkId,
          status: frameworkStatus,
          controlReadiness,
          lastUpdated: now(),
        },
      };
    },
  };
}
/**
 * Storage adapter integration: compfn schema + @superfunctions/db adapter.
 * Callers pass Adapter in CompFnConfig; this module provides schema and helpers for namespace.
 */

import type { Adapter, TableSchemaMap } from "@superfunctions/db";
import { getCompfnSchemaMap, type CompfnSchemaOptions } from "./schema.js";

export type { CompfnSchemaOptions } from "./schema.js";
export { getCompfnSchema, getCompfnSchemaMap } from "./schema.js";

/**
 * Get schema map for the given namespace (for createSchema / validateSchema with the db adapter).
 */
export function getSchemaForAdapter(options: CompfnSchemaOptions = {}): TableSchemaMap {
  return getCompfnSchemaMap(options);
}

/**
 * Create or migrate schema using the provided adapter.
 * Calls createSchema where provided, otherwise validateSchema. Drizzle migrations are host-owned.
 */
export async function createSchemaIfSupported(
  database: Adapter,
  options: CompfnSchemaOptions = {}
): Promise<{ success: boolean; errors?: string[] }> {
  const schema = getCompfnSchemaMap(options);
  const namespace = options.namespace ?? "compfn";

  if (typeof database.createSchema !== "function") {
    // Validate each table instead
    const tables = Object.values(schema);
    for (const table of tables) {
      const result = await database.validateSchema(table);
      if (!result.valid) {
        return { success: false, errors: result.errors?.length ? result.errors : [`Schema validation failed for ${table.modelName}`] };
      }
    }
    return { success: true };
  }

  const result = await database.createSchema({ schema, namespace });
  return {
    success: result.success,
    errors: result.errors,
  };
}
import { randomUUID } from "node:crypto";
/**
 * Evidence service: create, get, list (immutable; no update/delete).
 * Validates controlId exists, type in EvidenceType, payload size ≤ evidencePayloadMaxBytes.
 * Returns VALIDATION_FAILED for invalid controlId or type; PAYLOAD_TOO_LARGE when payload exceeds limit.
 */

import type { Adapter } from "@superfunctions/db";
import type { Evidence, CreateEvidenceInput } from "../evidence.js";
import type { CompfnEnvelope } from "../errors.js";
import type { Logger } from "../logger.js";
import { validateCreateEvidenceInput } from "../validation.js";
import { EVIDENCE_PAYLOAD_MAX_BYTES_DEFAULT } from "../constants.js";
import { defaultLogger } from "../logger.js";

const MODEL = "evidence";

export interface EvidenceServiceConfig {
  database: Adapter;
  namespace?: string;
  evidencePayloadMaxBytes?: number;
  /** Check that a control exists (e.g. controls.get(id).then(r => r.ok)) */
  existsControl: (controlId: string) => Promise<CompfnEnvelope<boolean>>;
  /** Get framework by id to resolve requirement controlIds (for list by frameworkId) */
  getFramework: (frameworkId: string) => Promise<{ requirements: { controlIds: string[] }[] } | null>;
